// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Job status, stage, token usage, proposal, dry-run traces, problems and diff
	// (GET /ai/jobs/{jobId})
	GetAIJob(w http.ResponseWriter, r *http.Request, jobId openapi_types.UUID)
	// Save the proposal as a new scenario or a new scenario version
	// (POST /ai/jobs/{jobId}/approve)
	ApproveAIJob(w http.ResponseWriter, r *http.Request, jobId openapi_types.UUID)
	// AI providers configured for the organisation (keys are never returned)
	// (GET /ai/providers)
	ListAIProviders(w http.ResponseWriter, r *http.Request)
	// Create or replace an AI provider by name
	// (POST /ai/providers)
	PutAIProvider(w http.ResponseWriter, r *http.Request)

	// (DELETE /ai/providers/{providerId})
	DeleteAIProvider(w http.ResponseWriter, r *http.Request, providerId openapi_types.UUID)

	// (GET /audit)
	ListAudit(w http.ResponseWriter, r *http.Request, params ListAuditParams)
	// How people can sign in (public)
	// (GET /auth/config)
	GetAuthConfig(w http.ResponseWriter, r *http.Request)

	// (POST /auth/login)
	Login(w http.ResponseWriter, r *http.Request)

	// (POST /auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// Compare finished runs of version A with runs of version B
	// (POST /compare)
	CompareRuns(w http.ResponseWriter, r *http.Request)
	// One drift check with its redacted dry-run traces and spec diff
	// (GET /drift-results/{driftId})
	GetDriftResult(w http.ResponseWriter, r *http.Request, driftId DriftId)
	// Ask the AI generator to repair the broken journeys (asynchronous)
	// (POST /drift-results/{driftId}/repair)
	RepairDrift(w http.ResponseWriter, r *http.Request, driftId DriftId)
	// Integrations configured for the organisation (tokens are never returned)
	// (GET /integrations)
	ListIntegrations(w http.ResponseWriter, r *http.Request)
	// Add a named Prometheus or traces integration
	// (POST /integrations)
	CreateIntegration(w http.ResponseWriter, r *http.Request)

	// (DELETE /integrations/{integrationId})
	DeleteIntegration(w http.ResponseWriter, r *http.Request, integrationId openapi_types.UUID)

	// (GET /me)
	GetMe(w http.ResponseWriter, r *http.Request)

	// (PUT /me/password)
	ChangePassword(w http.ResponseWriter, r *http.Request)
	// Notification channels of the organisation (URLs and secrets are never returned)
	// (GET /notifications/channels)
	ListNotificationChannels(w http.ResponseWriter, r *http.Request)
	// Add a webhook, Slack or Discord channel
	// (POST /notifications/channels)
	CreateNotificationChannel(w http.ResponseWriter, r *http.Request)

	// (DELETE /notifications/channels/{channelId})
	DeleteNotificationChannel(w http.ResponseWriter, r *http.Request, channelId ChannelId)
	// The most recent delivery attempts of a channel, newest first
	// (GET /notifications/channels/{channelId}/deliveries)
	ListNotificationDeliveries(w http.ResponseWriter, r *http.Request, channelId ChannelId, params ListNotificationDeliveriesParams)
	// Send a test notification now (one attempt, no retries)
	// (POST /notifications/channels/{channelId}/test)
	TestNotificationChannel(w http.ResponseWriter, r *http.Request, channelId ChannelId)
	// The organisation's hard caps on every run
	// (GET /organisation/caps)
	GetOrgCaps(w http.ResponseWriter, r *http.Request)
	// Set the organisation's hard caps (admin)
	// (PUT /organisation/caps)
	PutOrgCaps(w http.ResponseWriter, r *http.Request)
	// The product packs built into this server
	// (GET /packs)
	ListPacks(w http.ResponseWriter, r *http.Request)
	// A shipped pack with its journey and stress scenarios
	// (GET /packs/{packName})
	GetPack(w http.ResponseWriter, r *http.Request, packName string)

	// (GET /projects)
	ListProjects(w http.ResponseWriter, r *http.Request)

	// (POST /projects)
	CreateProject(w http.ResponseWriter, r *http.Request)

	// (DELETE /projects/{projectId})
	DeleteProject(w http.ResponseWriter, r *http.Request, projectId ProjectId)

	// (GET /projects/{projectId})
	GetProject(w http.ResponseWriter, r *http.Request, projectId ProjectId)

	// (PATCH /projects/{projectId})
	UpdateProject(w http.ResponseWriter, r *http.Request, projectId ProjectId)

	// (GET /projects/{projectId}/ai/jobs)
	ListAIJobs(w http.ResponseWriter, r *http.Request, projectId ProjectId, params ListAIJobsParams)
	// Generate a scenario with an AI model (asynchronous)
	// (POST /projects/{projectId}/ai/jobs)
	CreateAIJob(w http.ResponseWriter, r *http.Request, projectId ProjectId)
	// Results of scheduled drift checks, newest first
	// (GET /projects/{projectId}/drift-results)
	ListDriftResults(w http.ResponseWriter, r *http.Request, projectId ProjectId, params ListDriftResultsParams)
	// Per-project role overrides
	// (GET /projects/{projectId}/roles)
	ListProjectRoles(w http.ResponseWriter, r *http.Request, projectId ProjectId)
	// Remove an override, so the organisation role applies again (admin)
	// (DELETE /projects/{projectId}/roles/{userId})
	DeleteProjectRole(w http.ResponseWriter, r *http.Request, projectId ProjectId, userId UserId)
	// Give a member a different role in this project (admin)
	// (PUT /projects/{projectId}/roles/{userId})
	PutProjectRole(w http.ResponseWriter, r *http.Request, projectId ProjectId, userId UserId)

	// (GET /projects/{projectId}/runs)
	ListRuns(w http.ResponseWriter, r *http.Request, projectId ProjectId, params ListRunsParams)

	// (POST /projects/{projectId}/runs)
	CreateRun(w http.ResponseWriter, r *http.Request, projectId ProjectId)

	// (GET /projects/{projectId}/scenarios)
	ListScenarios(w http.ResponseWriter, r *http.Request, projectId ProjectId, params ListScenariosParams)

	// (POST /projects/{projectId}/scenarios)
	CreateScenario(w http.ResponseWriter, r *http.Request, projectId ProjectId)

	// (GET /projects/{projectId}/schedules)
	ListSchedules(w http.ResponseWriter, r *http.Request, projectId ProjectId)
	// Create a schedule
	// (POST /projects/{projectId}/schedules)
	CreateSchedule(w http.ResponseWriter, r *http.Request, projectId ProjectId)

	// (GET /projects/{projectId}/secrets)
	ListSecrets(w http.ResponseWriter, r *http.Request, projectId ProjectId)

	// (PUT /projects/{projectId}/secrets)
	PutSecret(w http.ResponseWriter, r *http.Request, projectId ProjectId)

	// (DELETE /projects/{projectId}/secrets/{name})
	DeleteSecret(w http.ResponseWriter, r *http.Request, projectId ProjectId, name string)

	// (GET /projects/{projectId}/settings)
	GetProjectSettings(w http.ResponseWriter, r *http.Request, projectId ProjectId)
	// Set the project's caps and dry-run gate (admin)
	// (PUT /projects/{projectId}/settings)
	PutProjectSettings(w http.ResponseWriter, r *http.Request, projectId ProjectId)

	// (GET /projects/{projectId}/targets)
	ListTargets(w http.ResponseWriter, r *http.Request, projectId ProjectId)

	// (POST /projects/{projectId}/targets)
	CreateTarget(w http.ResponseWriter, r *http.Request, projectId ProjectId)
	// Kill switch for every active run in the organisation
	// (POST /runs/kill-all)
	KillAllRuns(w http.ResponseWriter, r *http.Request)

	// (GET /runs/{runId})
	GetRun(w http.ResponseWriter, r *http.Request, runId RunId)
	// Events recorded for a run
	// (GET /runs/{runId}/events)
	ListRunEvents(w http.ResponseWriter, r *http.Request, runId RunId)
	// Kill switch for one run; all load stops immediately
	// (POST /runs/{runId}/kill)
	KillRun(w http.ResponseWriter, r *http.Request, runId RunId)
	// Live metrics as server-sent events
	// (GET /runs/{runId}/live)
	StreamRun(w http.ResponseWriter, r *http.Request, runId RunId)
	// Write an AI summary of a finished run's report
	// (POST /runs/{runId}/narrative)
	CreateRunNarrative(w http.ResponseWriter, r *http.Request, runId RunId)

	// (GET /runs/{runId}/report)
	GetRunReport(w http.ResponseWriter, r *http.Request, runId RunId, params GetRunReportParams)
	// Stop gracefully; in-flight iterations may finish
	// (POST /runs/{runId}/stop)
	StopRun(w http.ResponseWriter, r *http.Request, runId RunId)

	// (GET /runs/{runId}/timeline)
	GetRunTimeline(w http.ResponseWriter, r *http.Request, runId RunId, params GetRunTimelineParams)
	// Health of the load generators running a run
	// (GET /runs/{runId}/workers)
	ListRunWorkers(w http.ResponseWriter, r *http.Request, runId RunId)

	// (POST /scenarios/validate)
	ValidateScenario(w http.ResponseWriter, r *http.Request)

	// (DELETE /scenarios/{scenarioId})
	DeleteScenario(w http.ResponseWriter, r *http.Request, scenarioId ScenarioId)

	// (GET /scenarios/{scenarioId})
	GetScenario(w http.ResponseWriter, r *http.Request, scenarioId ScenarioId)
	// Which endpoints of an API the scenario's journeys exercise
	// (POST /scenarios/{scenarioId}/coverage)
	ScenarioCoverage(w http.ResponseWriter, r *http.Request, scenarioId ScenarioId)
	// Find journeys an API change broke
	// (POST /scenarios/{scenarioId}/drift)
	ScenarioDrift(w http.ResponseWriter, r *http.Request, scenarioId ScenarioId)

	// (GET /scenarios/{scenarioId}/versions)
	ListScenarioVersions(w http.ResponseWriter, r *http.Request, scenarioId ScenarioId)

	// (POST /scenarios/{scenarioId}/versions)
	CreateScenarioVersion(w http.ResponseWriter, r *http.Request, scenarioId ScenarioId)

	// (GET /scenarios/{scenarioId}/versions/{version})
	GetScenarioVersion(w http.ResponseWriter, r *http.Request, scenarioId ScenarioId, version int)
	// The next times a cron expression fires
	// (GET /schedules/preview)
	PreviewSchedule(w http.ResponseWriter, r *http.Request, params PreviewScheduleParams)

	// (DELETE /schedules/{scheduleId})
	DeleteSchedule(w http.ResponseWriter, r *http.Request, scheduleId ScheduleId)

	// (GET /schedules/{scheduleId})
	GetSchedule(w http.ResponseWriter, r *http.Request, scheduleId ScheduleId)
	// Change a schedule, or enable or disable it
	// (PATCH /schedules/{scheduleId})
	UpdateSchedule(w http.ResponseWriter, r *http.Request, scheduleId ScheduleId)
	// Start the schedule's run now
	// (POST /schedules/{scheduleId}/run)
	RunSchedule(w http.ResponseWriter, r *http.Request, scheduleId ScheduleId)
	// The server's load caps and every target's caps (admin)
	// (GET /settings/limits)
	GetLimitSettings(w http.ResponseWriter, r *http.Request)
	// The server's single sign-on configuration (admin)
	// (GET /settings/sso)
	GetSSOSettings(w http.ResponseWriter, r *http.Request)
	// Create the first organisation and owner account
	// (POST /setup)
	Setup(w http.ResponseWriter, r *http.Request)

	// (DELETE /targets/{targetId})
	DeleteTarget(w http.ResponseWriter, r *http.Request, targetId TargetId)

	// (GET /targets/{targetId})
	GetTarget(w http.ResponseWriter, r *http.Request, targetId TargetId)

	// (PATCH /targets/{targetId})
	UpdateTarget(w http.ResponseWriter, r *http.Request, targetId TargetId)
	// Check the ownership token for a public target
	// (POST /targets/{targetId}/verify)
	VerifyTarget(w http.ResponseWriter, r *http.Request, targetId TargetId)

	// (GET /tokens)
	ListTokens(w http.ResponseWriter, r *http.Request)

	// (POST /tokens)
	CreateToken(w http.ResponseWriter, r *http.Request)

	// (DELETE /tokens/{tokenId})
	DeleteToken(w http.ResponseWriter, r *http.Request, tokenId TokenId)

	// (GET /users)
	ListUsers(w http.ResponseWriter, r *http.Request)

	// (POST /users)
	CreateUser(w http.ResponseWriter, r *http.Request)

	// (DELETE /users/{userId})
	DeleteUser(w http.ResponseWriter, r *http.Request, userId UserId)

	// (PATCH /users/{userId})
	UpdateUser(w http.ResponseWriter, r *http.Request, userId UserId)

	// (GET /version)
	GetVersion(w http.ResponseWriter, r *http.Request)

	// (GET /workers)
	ListWorkers(w http.ResponseWriter, r *http.Request)
}

